import mx.eloeste.core.*;
import mx.eloeste.desktop.*;
import org.json.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicLong;

public final class ContinuationTests {
    static int checks=0;
    static void ok(boolean value,String label) { checks++; if(!value) throw new AssertionError(label); }
    static long at(String date) { return LocalDateTime.parse(date).atZone(ZoneId.of(Rules.ZONE)).toInstant().toEpochMilli(); }
    static JSONObject contract(String mode,long start,long end,boolean pay) { return new JSONObject().put("mode",mode).put("start",start).put("end",end).put("vehicle",OesteTests.vehicle("auto")).put("received",mode.equals("12h")?50000:60000).put("manualDatesConfirmed",true).put("payNow",pay); }
    static void config(OesteTests.Client c,java.util.function.Consumer<JSONObject> edit) { JSONObject state=c.get("state"),rates=state.getJSONObject("config"); edit.accept(rates); Api.Reply r=c.post("config",new JSONObject().put("version",state.getInt("version")).put("config",rates).put("reason","Configuración explícita para pruebas")); ok(r.status==200,"save config: "+r.json); }
    public static void main(String[] args) throws Exception {
        AtomicLong clock=new AtomicLong(at("2026-11-12T09:00"));
        try(JdbcDb db=new JdbcDb(":memory:")) {
            Api api=new Api(db,clock::get); api.bootstrap("admin","65432198"); OesteTests.Client admin=new OesteTests.Client(api,"admin","65432198");
            JSONObject rates=Rules.defaults(); ok(rates.getLong("freeNormal")==5000&&rates.getLong("freePreferred")==6000,"free tariffs retain confirmed direction");
            for(boolean preferred:new boolean[]{false,true}) { JSONObject service=new JSONObject().put("mode","free").put("preferred",preferred).put("wash","").put("rates",rates);Rules.attachCoverage(service,clock.get(),rates);JSONObject stay=new JSONObject().put("entered",clock.get()).put("service",service.toString()),q=Rules.quote(stay,clock.get()+3600000);ok(q.getLong("total")== (preferred?6000:5000)&&q.getBoolean("blocked"),"free is fixed but undefined coverage blocked"); }
            config(admin,c->c.put("opening","08:00").put("closing","20:00"));
            for(boolean preferred:new boolean[]{false,true}) { JSONObject b=OesteTests.entry(1,"free","");b.getJSONObject("service").put("preferred",preferred);String id=admin.post("entry",b).json.getString("id");JSONObject q=admin.get("state").getJSONArray("stays").getJSONObject(0).getJSONObject("quote");ok(q.getLong("total")== (preferred?6000:5000)&&!q.getBoolean("blocked"),"free covered without hourly");Api.Reply paid=admin.post("checkout",OesteTests.checkout(id,10000));ok(paid.status==200&&paid.json.getLong("total")== (preferred?6000:5000),"free checkout correct"); }
            JSONObject freeWash=OesteTests.entry(1,"free","pickup");String fw=admin.post("entry",freeWash).json.getString("id");ok(admin.post("checkout",OesteTests.checkout(fw,25000)).json.getLong("total")==25000,"independent free+pickup wash is 250, not addon 230");
            JSONObject pending=admin.post("monthly",contract("24h",clock.get()-1000,clock.get()+20*86400000L,false)).json;ok(pending.getBoolean("unpaid"),"unpaid monthly registration");String mid=pending.getString("id");JSONObject monthlyEntry=OesteTests.entry(1,"monthly","");monthlyEntry.getJSONObject("service").put("monthlyId",mid);ok(admin.post("entry",monthlyEntry).status==400,"unpaid pension cannot provide coverage");
            String payKey=OesteTests.key();JSONObject pay=new JSONObject().put("id",mid).put("received",60000);Api.Reply p=admin.post("monthly-pay",pay,payKey);ok(p.status==200&&p.json.getLong("total")==60000,"monthly 24 payment once");ok(admin.post("monthly-pay",pay,payKey).json.getString("id").equals(p.json.getString("id")),"monthly payment retry");ok(admin.post("monthly-pay",pay).status==400,"different retry key cannot pay twice");
            String id=admin.post("entry",monthlyEntry).json.getString("id");clock.addAndGet(2*3600000);JSONObject q=admin.get("state").getJSONArray("stays").getJSONObject(0).getJSONObject("quote");ok(q.getLong("total")==0&&!q.getBoolean("blocked"),"paid 24h covers entry without hourly");int before=db.one("SELECT COUNT(*) AS n FROM payments").getInt("n");Api.Reply exit=admin.post("checkout",OesteTests.checkout(id,0));ok(exit.status==200&&exit.json.getBoolean("covered"),"covered exit recorded");ok(db.one("SELECT COUNT(*) AS n FROM payments").getInt("n")==before,"covered exit is not another financial payment");
            JSONObject nocturnal=admin.post("monthly",contract("12h",clock.get()-86400000,clock.get()+25*86400000L,true)).json;String nid=db.one("SELECT id FROM monthly ORDER BY created DESC LIMIT 1").getString("id"); // Select explicitly below when fake timestamps tie.
            JSONArray contracts=admin.get("state").getJSONArray("monthly");for(int i=0;i<contracts.length();i++){JSONObject m=contracts.getJSONObject(i);if(new JSONObject(m.getString("mode")).getInt("hours")==12)nid=m.getString("id");}
            JSONObject ne=OesteTests.entry(1,"monthly","");ne.getJSONObject("service").put("monthlyId",nid);String ns=admin.post("entry",ne).json.getString("id");ok(admin.get("state").getJSONArray("stays").getJSONObject(0).getJSONObject("quote").getBoolean("blocked"),"12h night schedule remains pending");ok(admin.post("checkout",OesteTests.checkout(ns,0).put("resolution",new JSONObject().put("extraCents",0).put("reason","Resolución explícita sin importe adicional"))).status==200,"pending night requires admin decision");
            config(admin,c->c.put("monthlyNightStart","20:00").put("monthlyNightEnd","08:00"));clock.set(at("2026-11-12T21:00"));admin=new OesteTests.Client(api,"admin","65432198");ns=admin.post("entry",ne).json.getString("id");clock.set(at("2026-11-13T07:59"));q=admin.get("state").getJSONArray("stays").getJSONObject(0).getJSONObject("quote");ok(q.getLong("total")==0&&!q.getBoolean("blocked"),"configured 12h crosses midnight");clock.set(at("2026-11-13T08:00:01"));q=admin.get("state").getJSONArray("stays").getJSONObject(0).getJSONObject("quote");ok(q.getBoolean("blocked")&&q.getLong("total")==0,"night excess has no invented charge");admin.post("checkout",OesteTests.checkout(ns,0).put("resolution",new JSONObject().put("extraCents",0).put("reason","Salida autorizada sin recargo automático")));
            admin.post("users",new JSONObject().put("name","turno_a").put("password","11122233").put("role","employee"));admin.post("users",new JSONObject().put("name","turno_b").put("password","44455566").put("role","employee"));OesteTests.Client a=new OesteTests.Client(api,"turno_a","11122233"),b=new OesteTests.Client(api,"turno_b","44455566");id=a.post("entry",OesteTests.entry(1,"hourly","")).json.getString("id");clock.addAndGet(3600001);JSONObject stale=OesteTests.checkout(id,10000).put("expectedTotal",1500);ok(b.post("checkout",stale).status==400,"changed quote requires new review");ok(b.post("checkout",OesteTests.checkout(id,2500)).status==200,"another employee may collect");JSONObject history=a.get("history?from=2026-11-12&to=2026-11-13");ok(history.getLong("total")==0,"employee cannot see another employee cash");ok(b.get("history?from=2026-11-12&to=2026-11-13").getLong("total")==2500,"own historical cash");ok(b.post("backup",new JSONObject().put("password","test-backup-password")).status==400,"employee cannot export database");
            admin=new OesteTests.Client(api,"admin","65432198");id=a.post("entry",OesteTests.entry(1,"hourly","")).json.getString("id");String old=db.one("SELECT token FROM cards WHERE id=1").getString("token");ok(a.post("lost-card",new JSONObject().put("id",id).put("reason","Tarjeta reportada como extraviada")).status==400,"loss requires reinforced confirmation");ok(a.post("lost-card",new JSONObject().put("id",id).put("reason","Tarjeta reportada como extraviada").put("vehicleConfirmed",true).put("lossConfirmed",true)).status==200,"confirmed loss");ok(a.post("scan",new JSONObject().put("token",old)).status==400,"revoked QR rejected");ok(admin.post("replace-card",new JSONObject().put("id",id).put("card",31).put("reason","Uso de reserva tras extravío")).status==200,"admin replacement reserve");ok(db.one("SELECT card_id FROM stays WHERE id=?",id).getInt("card_id")==31,"active stay moved atomically to reserve");
            JSONObject backup=admin.post("backup",new JSONObject().put("password","test-backup-password")).json.getJSONObject("backup");ok(!backup.toString().contains("TEST123")&&!backup.toString().contains(old),"encrypted export contains no visible vehicle or QR");String savedId=id;JSONObject wrong=new JSONObject().put("backup",backup).put("password","wrong-backup-password").put("pin","65432198").put("confirmation","RESTAURAR");ok(admin.post("restore",wrong).status==400,"wrong backup password blocked");ok(db.one("SELECT state FROM stays WHERE id=?",savedId).getString("state").equals("active"),"failed restore preserves database");admin.post("checkout",OesteTests.checkout(id,20000));ok(admin.post("restore",new JSONObject().put("backup",backup).put("password","test-backup-password").put("pin","65432198").put("confirmation","RESTAURAR")).status==200,"encrypted restore succeeds");admin=new OesteTests.Client(api,"admin","65432198");ok(admin.get("state").getJSONArray("stays").length()==1,"active stay recovered from backup");ok(db.one("SELECT COUNT(*) AS n FROM sessions").getInt("n")==1,"restored sessions revoked, only new login remains");
            JSONObject report=admin.get("report?date=2026-11-12");ok(report.getJSONObject("categories").getLong("time_free_normal")==10000&&report.getJSONObject("categories").getLong("time_free_preferred")==6000,"reports split free normal and preferred");ok(report.getJSONObject("categories").getLong("pension_monthly_12")==50000&&report.getJSONObject("categories").getLong("pension_monthly_24")==60000,"monthly income recorded only on payment date");
            for(int i=0;i<5;i++)api.handle("POST","/api/login",new JSONObject().put("name","turno_a").put("password","000000"),"","","");ok(api.handle("POST","/api/login",new JSONObject().put("name","turno_a").put("password","11122233"),"","","").status==429,"PIN lockout after repeated attempts");
            JSONObject me=db.one("SELECT id FROM users WHERE name='admin'");ok(admin.post("user-update",new JSONObject().put("id",me.getString("id")).put("active",false).put("role","employee")).status==400,"last admin preserved");
        }
        System.out.println("PASS · "+checks+" verificaciones nuevas de tiempo libre, mensualidades, PIN, privacidad y respaldos.");
    }
}
